class Solution:
    def equalCountSubstrings(self, s: str, count: int) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            freq = [0] * 26
            distinct = 0
            matched = 0
            for j in range(i, n):
                c = ord(s[j]) - 97
                freq[c] += 1
                if freq[c] == 1:
                    distinct += 1
                if freq[c] == count:
                    matched += 1
                elif freq[c] == count + 1:
                    matched -= 1
                if matched == distinct:
                    ans += 1
        return ans

