class Solution:
    def equalCountSubstrings(self, s: str, count: int) -> int:
        n = len(s)
        ans = 0
        for u in range(1, 27):
            w = u * count
            if w > n:
                break
            freq = [0] * 26
            match = 0
            for i in range(n):
                c = ord(s[i]) - 97
                freq[c] += 1
                if freq[c] == count:
                    match += 1
                elif freq[c] == count + 1:
                    match -= 1
                if i >= w:
                    d = ord(s[i - w]) - 97
                    freq[d] -= 1
                    if freq[d] == count:
                        match += 1
                    elif freq[d] == count - 1:
                        match -= 1
                if i >= w - 1 and match == u:
                    ans += 1
        return ans

