                int c = s[i] - 'a';
                if (++freq[c] == count) match++;
                else if (freq[c] == count + 1) match--;
                if (i >= w) {
                    int d = s[i - w] - 'a';
                    if (--freq[d] == count) match++;
                    else if (freq[d] == count - 1) match--;
                }
                if (i >= w - 1 && match == u) ans++;
            }
        }
        return ans;
    }
};

